func RuleFor(code string) (QualificationRule, bool) {
	for _, r := range QualificationCatalog {
		if r.Code == code {
			return r, true
		}
	}
	return QualificationRule{}, false
}
func RulesForSport(sport string) []QualificationRule {
	out := []QualificationRule{}
	for _, r := range QualificationCatalog {
		if r.Sport == sport {
			out = append(out, r)
		}
	}
	return out
}
func RulesForLevel(level string) []QualificationRule {
	out := []QualificationRule{}
	for _, r := range QualificationCatalog {
		if r.Level == level {
			out = append(out, r)
		}
	}
	return out
}
